-- ============================================================================
-- PPAI SSD 2026 - EASA | BASE DE DATOS TRANSACCIONAL (OLTP)
-- Fuente: DER-Optimizado.png, entregado por el Grupo 1.
-- Motor: PostgreSQL 15+ | Codificacion: UTF-8
--
-- EJECUCION: conectarse primero a la base easa_oltp y ejecutar este archivo.
-- El archivo NO crea la base de datos; para eso consultar 00_crear_base.sql.
--
-- Convenciones:
--   - Tablas y atributos del DER traducidos a snake_case.
--   - Claves tecnicas BIGINT GENERATED BY DEFAULT AS IDENTITY.
--   - Dinero: NUMERIC, nunca FLOAT.
--   - cantidad: NUMERIC(16,3), porque existen productos vendidos por peso.
--   - FKs opcionales solo donde el contexto permite ausencia.
--   - No se incluyen datos inventados ni tablas analiticas del DW.
-- ============================================================================

BEGIN;

-- ==========================================================================
-- 1. TABLAS DE REFERENCIA: sucursales, empleados, usuarios y estados
-- ==========================================================================

CREATE TABLE ciudad (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(120) NOT NULL UNIQUE
);

CREATE TABLE sucursal (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(150) NOT NULL UNIQUE,
    direccion VARCHAR(250) NOT NULL,
    ciudad_id BIGINT NOT NULL REFERENCES ciudad(id),
    tiene_planta BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE area (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(120) NOT NULL UNIQUE,
    descripcion TEXT
);

CREATE TABLE rol_empleado (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(120) NOT NULL,
    descripcion TEXT,
    area_id BIGINT NOT NULL REFERENCES area(id),
    CONSTRAINT uq_rol_empleado_area UNIQUE (nombre, area_id)
);

CREATE TABLE empleado (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(120) NOT NULL,
    apellido VARCHAR(120) NOT NULL,
    salario_x_hora NUMERIC(14,2) NOT NULL CHECK (salario_x_hora >= 0),
    rol_id BIGINT NOT NULL REFERENCES rol_empleado(id),
    telefono VARCHAR(50),
    email VARCHAR(254),
    cuit VARCHAR(20),
    cuil VARCHAR(20),
    CONSTRAINT uq_empleado_cuil UNIQUE (cuil)
);

CREATE TABLE rol_usuario (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(120) NOT NULL UNIQUE,
    descripcion TEXT
);

CREATE TABLE usuario (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(120) NOT NULL UNIQUE,
    email VARCHAR(254) NOT NULL UNIQUE,
    -- DER: 'contrasena'. Implementacion: almacenar un hash, NUNCA texto plano.
    contrasena_hash TEXT NOT NULL,
    rol_id BIGINT NOT NULL REFERENCES rol_usuario(id)
);

CREATE TABLE auditoria (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha_hora TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    accion VARCHAR(100) NOT NULL,
    entidad VARCHAR(120) NOT NULL,
    id_entidad BIGINT NOT NULL,
    usuario_id BIGINT NOT NULL REFERENCES usuario(id)
);

-- DER: Estado es un catalogo comun; el campo ambito distingue compra,
-- venta, cheque, etc. La FK sola no controla el ambito: hacerlo en la app.
CREATE TABLE estado (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ambito VARCHAR(80) NOT NULL,
    nombre VARCHAR(120) NOT NULL,
    CONSTRAINT uq_estado_ambito_nombre UNIQUE (ambito, nombre)
);

-- ==========================================================================
-- 2. PRODUCTOS, INSUMOS, UNIDADES, RECETAS Y PRECIOS
-- ==========================================================================

CREATE TABLE unidad (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(80) NOT NULL,          -- DER: name
    descripcion TEXT,
    scope VARCHAR(60),                    -- DER: scope
    CONSTRAINT uq_unidad_nombre_scope UNIQUE (nombre, scope)
);

CREATE TABLE tipo_producto (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(120) NOT NULL UNIQUE,
    descripcion TEXT
);

CREATE TABLE producto (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(150) NOT NULL UNIQUE,
    unidad_id BIGINT NOT NULL REFERENCES unidad(id),
    unidades_x_receta NUMERIC(16,3) NOT NULL CHECK (unidades_x_receta > 0),
    cantidad_esperada_mes NUMERIC(16,3) NOT NULL DEFAULT 0
        CHECK (cantidad_esperada_mes >= 0),
    horas_mano_de_obra_x_receta NUMERIC(12,3) NOT NULL DEFAULT 0
        CHECK (horas_mano_de_obra_x_receta >= 0),
    -- DER: FactorComplejidad presenta valores UNO=1, UNO_Y_MEDIO=1.5, DOS=2.
    factor_complejidad NUMERIC(3,1) NOT NULL DEFAULT 1.0
        CHECK (factor_complejidad IN (1.0, 1.5, 2.0)),
    tipo_producto_id BIGINT NOT NULL REFERENCES tipo_producto(id)
);

CREATE TABLE insumo (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(150) NOT NULL UNIQUE,
    unidad_id BIGINT NOT NULL REFERENCES unidad(id)
);

CREATE TABLE item_receta (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    insumo_id BIGINT NOT NULL REFERENCES insumo(id),
    cantidad NUMERIC(16,3) NOT NULL CHECK (cantidad > 0),
    producto_id BIGINT NOT NULL REFERENCES producto(id),
    CONSTRAINT uq_item_receta_producto_insumo UNIQUE (producto_id, insumo_id)
);

-- ==========================================================================
-- 3. CLIENTES, TIPOS DE CLIENTE, PROMOCIONES Y PRECIOS DE PRODUCTOS
-- ==========================================================================

CREATE TABLE tipo_cliente (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(120) NOT NULL UNIQUE,
    descripcion TEXT
);

CREATE TABLE cliente (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    razon_social VARCHAR(200) NOT NULL,
    telefono VARCHAR(50),
    email VARCHAR(254),
    cuit VARCHAR(20),
    cuil VARCHAR(20),
    tipo_cliente_id BIGINT NOT NULL REFERENCES tipo_cliente(id),
    CONSTRAINT uq_cliente_cuit UNIQUE (cuit),
    CONSTRAINT uq_cliente_cuil UNIQUE (cuil)
);

CREATE TABLE precio_producto (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    producto_id BIGINT NOT NULL REFERENCES producto(id),
    tipo_cliente_id BIGINT NOT NULL REFERENCES tipo_cliente(id),
    precio NUMERIC(14,4) NOT NULL CHECK (precio >= 0),
    fecha_desde DATE NOT NULL,
    fecha_hasta DATE,
    CONSTRAINT ck_precio_producto_fechas
        CHECK (fecha_hasta IS NULL OR fecha_hasta >= fecha_desde),
    CONSTRAINT uq_precio_producto_vigencia
        UNIQUE (producto_id, tipo_cliente_id, fecha_desde)
);

CREATE TABLE tipo_promocion (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(120) NOT NULL UNIQUE,
    descripcion TEXT
);

CREATE TABLE promocion (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(150) NOT NULL,
    fecha_desde DATE NOT NULL,
    fecha_hasta DATE NOT NULL,
    valor NUMERIC(14,2) NOT NULL CHECK (valor >= 0),
    tipo_promocion_id BIGINT NOT NULL REFERENCES tipo_promocion(id),
    CONSTRAINT ck_promocion_fechas CHECK (fecha_hasta >= fecha_desde)
);

CREATE TABLE promocion_tipo_cliente (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    promocion_id BIGINT NOT NULL REFERENCES promocion(id),
    tipo_cliente_id BIGINT NOT NULL REFERENCES tipo_cliente(id),
    CONSTRAINT uq_promocion_tipo_cliente UNIQUE (promocion_id, tipo_cliente_id)
);

CREATE TABLE promocion_producto (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    promocion_id BIGINT NOT NULL REFERENCES promocion(id),
    producto_id BIGINT NOT NULL REFERENCES producto(id),
    CONSTRAINT uq_promocion_producto UNIQUE (promocion_id, producto_id)
);

-- ==========================================================================
-- 4. PROVEEDORES, PRECIOS DE INSUMOS Y COMPRAS
-- ==========================================================================

CREATE TABLE proveedor (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    razon_social VARCHAR(200) NOT NULL,
    telefono VARCHAR(50),
    email VARCHAR(254),
    cuit VARCHAR(20),
    cuil VARCHAR(20),
    CONSTRAINT uq_proveedor_cuit UNIQUE (cuit)
);

CREATE TABLE precio_insumo (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    insumo_id BIGINT NOT NULL REFERENCES insumo(id),
    precio NUMERIC(14,4) NOT NULL CHECK (precio >= 0),
    fecha_desde DATE NOT NULL,
    fecha_hasta DATE,
    proveedor_id BIGINT NOT NULL REFERENCES proveedor(id),
    CONSTRAINT ck_precio_insumo_fechas
        CHECK (fecha_hasta IS NULL OR fecha_hasta >= fecha_desde),
    CONSTRAINT uq_precio_insumo_vigencia
        UNIQUE (insumo_id, proveedor_id, fecha_desde)
);

CREATE TABLE compra (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha_hora TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    estado_id BIGINT NOT NULL REFERENCES estado(id),
    proveedor_id BIGINT NOT NULL REFERENCES proveedor(id)
);

-- ==========================================================================
-- 5. STOCK DE PRODUCTOS E INSUMOS POR SUCURSAL
-- ==========================================================================

CREATE TABLE producto_sucursal (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    producto_id BIGINT NOT NULL REFERENCES producto(id),
    sucursal_id BIGINT NOT NULL REFERENCES sucursal(id),
    stock_actual NUMERIC(16,3) NOT NULL DEFAULT 0 CHECK (stock_actual >= 0),
    stock_minimo NUMERIC(16,3) NOT NULL DEFAULT 0 CHECK (stock_minimo >= 0),
    activo BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT uq_producto_sucursal UNIQUE (producto_id, sucursal_id)
);

CREATE TABLE insumo_sucursal (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    insumo_id BIGINT NOT NULL REFERENCES insumo(id),
    sucursal_id BIGINT NOT NULL REFERENCES sucursal(id),
    stock_actual NUMERIC(16,3) NOT NULL DEFAULT 0 CHECK (stock_actual >= 0),
    stock_minimo NUMERIC(16,3) NOT NULL DEFAULT 0 CHECK (stock_minimo >= 0),
    CONSTRAINT uq_insumo_sucursal UNIQUE (insumo_id, sucursal_id)
);

-- Se declara aqui porque DetalleCompra apunta a InsumoSucursal.
CREATE TABLE detalle_compra (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    insumo_sucursal_id BIGINT NOT NULL REFERENCES insumo_sucursal(id),
    cantidad NUMERIC(16,3) NOT NULL CHECK (cantidad > 0),
    precio_unitario_historico NUMERIC(14,4) NOT NULL
        CHECK (precio_unitario_historico >= 0),
    compra_id BIGINT NOT NULL REFERENCES compra(id)
);

CREATE TABLE tipo_movimiento (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(120) NOT NULL UNIQUE,
    descripcion TEXT
);

-- En el DER, un movimiento afecta a un producto O un insumo de sucursal.
CREATE TABLE movimiento_stock (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cantidad NUMERIC(16,3) NOT NULL CHECK (cantidad <> 0),
    fecha_hora TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    tipo_id BIGINT NOT NULL REFERENCES tipo_movimiento(id),
    producto_sucursal_id BIGINT REFERENCES producto_sucursal(id),
    insumo_sucursal_id BIGINT REFERENCES insumo_sucursal(id),
    CONSTRAINT ck_movimiento_stock_un_solo_destino CHECK (
        (producto_sucursal_id IS NOT NULL AND insumo_sucursal_id IS NULL)
        OR
        (producto_sucursal_id IS NULL AND insumo_sucursal_id IS NOT NULL)
    )
);

CREATE TABLE ajuste_stock (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cantidad NUMERIC(16,3) NOT NULL CHECK (cantidad <> 0),
    fecha_hora TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    motivo TEXT NOT NULL,
    producto_sucursal_id BIGINT REFERENCES producto_sucursal(id),
    insumo_sucursal_id BIGINT REFERENCES insumo_sucursal(id),
    usuario_id BIGINT NOT NULL REFERENCES usuario(id),
    CONSTRAINT ck_ajuste_stock_un_solo_destino CHECK (
        (producto_sucursal_id IS NOT NULL AND insumo_sucursal_id IS NULL)
        OR
        (producto_sucursal_id IS NULL AND insumo_sucursal_id IS NOT NULL)
    )
);

-- ==========================================================================
-- 6. VENTAS Y SUS DETALLES
-- ==========================================================================

CREATE TABLE venta (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha_hora TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    estado_id BIGINT NOT NULL REFERENCES estado(id),
    cliente_id BIGINT NOT NULL REFERENCES cliente(id)
);

CREATE TABLE detalle_venta (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    producto_sucursal_id BIGINT NOT NULL REFERENCES producto_sucursal(id),
    cantidad NUMERIC(16,3) NOT NULL CHECK (cantidad > 0),
    precio_unitario_historico NUMERIC(14,4) NOT NULL
        CHECK (precio_unitario_historico >= 0),
    venta_id BIGINT NOT NULL REFERENCES venta(id),
    -- El DER permite que una linea de venta no tenga promocion.
    promocion_id BIGINT REFERENCES promocion(id)
);

-- ==========================================================================
-- 7. PRODUCCION, REPARTO Y COSTOS INDIRECTOS (CIF)
-- ==========================================================================

CREATE TABLE instancia_de_produccion (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha_hora TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    empleado_id BIGINT NOT NULL REFERENCES empleado(id),
    sucursal_id BIGINT NOT NULL REFERENCES sucursal(id)
);

CREATE TABLE detalle_instancia_de_produccion (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    producto_id BIGINT NOT NULL REFERENCES producto(id),
    cantidad NUMERIC(16,3) NOT NULL CHECK (cantidad > 0),
    instancia_produccion_id BIGINT NOT NULL REFERENCES instancia_de_produccion(id),
    CONSTRAINT uq_detalle_instancia_producto
        UNIQUE (instancia_produccion_id, producto_id)
);

CREATE TABLE reparto (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha_hora TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    instancia_produccion_id BIGINT NOT NULL REFERENCES instancia_de_produccion(id),
    sucursal_id BIGINT NOT NULL REFERENCES sucursal(id)
);

CREATE TABLE detalle_reparto (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cantidad NUMERIC(16,3) NOT NULL CHECK (cantidad > 0),
    reparto_id BIGINT NOT NULL REFERENCES reparto(id),
    detalle_instancia_produccion_id BIGINT NOT NULL
        REFERENCES detalle_instancia_de_produccion(id),
    CONSTRAINT uq_detalle_reparto UNIQUE (reparto_id, detalle_instancia_produccion_id)
);

CREATE TABLE tipo_cif (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(120) NOT NULL UNIQUE,
    descripcion TEXT
);

CREATE TABLE cif (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tipo_cif_id BIGINT NOT NULL REFERENCES tipo_cif(id),
    fecha_hora TIMESTAMP NOT NULL,
    monto NUMERIC(14,2) NOT NULL CHECK (monto >= 0)
);

-- ==========================================================================
-- 8. MEDIOS DE PAGO, CHEQUES, PAGOS Y COBROS
-- ==========================================================================

CREATE TABLE medio_pago (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(120) NOT NULL UNIQUE,
    descripcion TEXT
);

CREATE TABLE cheque (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    titular VARCHAR(200) NOT NULL,
    cuil VARCHAR(20),
    monto NUMERIC(14,2) NOT NULL CHECK (monto > 0),
    fecha_emision DATE NOT NULL,
    fecha_cobro DATE,
    estado_id BIGINT NOT NULL REFERENCES estado(id)
);

CREATE TABLE pago (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha_hora TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    medio_id BIGINT NOT NULL REFERENCES medio_pago(id),
    cheque_id BIGINT REFERENCES cheque(id),
    proveedor_id BIGINT NOT NULL REFERENCES proveedor(id)
);

CREATE TABLE detalle_pago (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    monto NUMERIC(14,2) NOT NULL CHECK (monto > 0),
    compra_id BIGINT NOT NULL REFERENCES compra(id),
    pago_id BIGINT NOT NULL REFERENCES pago(id),
    CONSTRAINT uq_detalle_pago_compra UNIQUE (pago_id, compra_id)
);

CREATE TABLE cobro (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha_hora TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    medio_id BIGINT NOT NULL REFERENCES medio_pago(id),
    cheque_id BIGINT REFERENCES cheque(id),
    cliente_id BIGINT NOT NULL REFERENCES cliente(id)
);

CREATE TABLE detalle_cobro (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    monto NUMERIC(14,2) NOT NULL CHECK (monto > 0),
    venta_id BIGINT NOT NULL REFERENCES venta(id),
    cobro_id BIGINT NOT NULL REFERENCES cobro(id),
    CONSTRAINT uq_detalle_cobro_venta UNIQUE (cobro_id, venta_id)
);

-- ==========================================================================
-- 9. INDICES RELEVANTES PARA CONSULTAS OLTP Y EXTRACCION ETL
--    Las PK, UNIQUE y UNIQUE compuesto ya generan indices.
-- ==========================================================================

CREATE INDEX idx_sucursal_ciudad ON sucursal(ciudad_id);
CREATE INDEX idx_empleado_rol ON empleado(rol_id);
CREATE INDEX idx_usuario_rol ON usuario(rol_id);
CREATE INDEX idx_auditoria_fecha ON auditoria(fecha_hora);
CREATE INDEX idx_auditoria_usuario ON auditoria(usuario_id);
CREATE INDEX idx_producto_tipo ON producto(tipo_producto_id);
CREATE INDEX idx_producto_unidad ON producto(unidad_id);
CREATE INDEX idx_insumo_unidad ON insumo(unidad_id);
CREATE INDEX idx_item_receta_insumo ON item_receta(insumo_id);
CREATE INDEX idx_cliente_tipo ON cliente(tipo_cliente_id);
CREATE INDEX idx_precio_producto_fecha ON precio_producto(fecha_desde);
CREATE INDEX idx_promocion_vigencia ON promocion(fecha_desde, fecha_hasta);
CREATE INDEX idx_promocion_producto_producto ON promocion_producto(producto_id);
CREATE INDEX idx_promocion_tipo_cliente_tipo ON promocion_tipo_cliente(tipo_cliente_id);
CREATE INDEX idx_precio_insumo_proveedor ON precio_insumo(proveedor_id);
CREATE INDEX idx_compra_fecha ON compra(fecha_hora);
CREATE INDEX idx_compra_proveedor ON compra(proveedor_id);
CREATE INDEX idx_detalle_compra_compra ON detalle_compra(compra_id);
CREATE INDEX idx_detalle_compra_insumo_sucursal ON detalle_compra(insumo_sucursal_id);
CREATE INDEX idx_producto_sucursal_sucursal ON producto_sucursal(sucursal_id);
CREATE INDEX idx_insumo_sucursal_sucursal ON insumo_sucursal(sucursal_id);
CREATE INDEX idx_movimiento_stock_fecha ON movimiento_stock(fecha_hora);
CREATE INDEX idx_movimiento_stock_producto_sucursal ON movimiento_stock(producto_sucursal_id);
CREATE INDEX idx_movimiento_stock_insumo_sucursal ON movimiento_stock(insumo_sucursal_id);
CREATE INDEX idx_ajuste_stock_fecha ON ajuste_stock(fecha_hora);
CREATE INDEX idx_ajuste_stock_producto_sucursal ON ajuste_stock(producto_sucursal_id);
CREATE INDEX idx_ajuste_stock_insumo_sucursal ON ajuste_stock(insumo_sucursal_id);
CREATE INDEX idx_venta_fecha ON venta(fecha_hora);
CREATE INDEX idx_venta_cliente ON venta(cliente_id);
CREATE INDEX idx_detalle_venta_venta ON detalle_venta(venta_id);
CREATE INDEX idx_detalle_venta_producto_sucursal ON detalle_venta(producto_sucursal_id);
CREATE INDEX idx_detalle_venta_promocion ON detalle_venta(promocion_id);
CREATE INDEX idx_produccion_fecha ON instancia_de_produccion(fecha_hora);
CREATE INDEX idx_produccion_sucursal ON instancia_de_produccion(sucursal_id);
CREATE INDEX idx_reparto_instancia ON reparto(instancia_produccion_id);
CREATE INDEX idx_reparto_sucursal ON reparto(sucursal_id);
CREATE INDEX idx_detalle_reparto_instancia ON detalle_reparto(detalle_instancia_produccion_id);
CREATE INDEX idx_cif_fecha ON cif(fecha_hora);
CREATE INDEX idx_pago_fecha ON pago(fecha_hora);
CREATE INDEX idx_pago_proveedor ON pago(proveedor_id);
CREATE INDEX idx_detalle_pago_compra ON detalle_pago(compra_id);
CREATE INDEX idx_cobro_fecha ON cobro(fecha_hora);
CREATE INDEX idx_cobro_cliente ON cobro(cliente_id);
CREATE INDEX idx_detalle_cobro_venta ON detalle_cobro(venta_id);

-- ==========================================================================
-- 10. REGLAS DE INTEGRIDAD ENTRE DETALLES (no visibles en el DER)
--     La FK valida cada referencia, pero no que ambos extremos correspondan
--     al mismo proveedor/cliente/instancia de produccion. Se validan aqui.
-- ==========================================================================

CREATE OR REPLACE FUNCTION validar_detalle_pago() RETURNS TRIGGER
LANGUAGE plpgsql AS $$
DECLARE
    v_proveedor_pago BIGINT;
    v_proveedor_compra BIGINT;
BEGIN
    SELECT proveedor_id INTO v_proveedor_pago
    FROM pago WHERE id = NEW.pago_id;

    SELECT proveedor_id INTO v_proveedor_compra
    FROM compra WHERE id = NEW.compra_id;

    IF v_proveedor_pago IS DISTINCT FROM v_proveedor_compra THEN
        RAISE EXCEPTION 'El pago % y la compra % deben ser del mismo proveedor',
            NEW.pago_id, NEW.compra_id;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_validar_detalle_pago
BEFORE INSERT OR UPDATE OF pago_id, compra_id
ON detalle_pago FOR EACH ROW EXECUTE FUNCTION validar_detalle_pago();

CREATE OR REPLACE FUNCTION validar_detalle_cobro() RETURNS TRIGGER
LANGUAGE plpgsql AS $$
DECLARE
    v_cliente_cobro BIGINT;
    v_cliente_venta BIGINT;
BEGIN
    SELECT cliente_id INTO v_cliente_cobro
    FROM cobro WHERE id = NEW.cobro_id;

    SELECT cliente_id INTO v_cliente_venta
    FROM venta WHERE id = NEW.venta_id;

    IF v_cliente_cobro IS DISTINCT FROM v_cliente_venta THEN
        RAISE EXCEPTION 'El cobro % y la venta % deben ser del mismo cliente',
            NEW.cobro_id, NEW.venta_id;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_validar_detalle_cobro
BEFORE INSERT OR UPDATE OF cobro_id, venta_id
ON detalle_cobro FOR EACH ROW EXECUTE FUNCTION validar_detalle_cobro();

CREATE OR REPLACE FUNCTION validar_detalle_reparto() RETURNS TRIGGER
LANGUAGE plpgsql AS $$
DECLARE
    v_instancia_reparto BIGINT;
    v_instancia_detalle BIGINT;
BEGIN
    SELECT instancia_produccion_id INTO v_instancia_reparto
    FROM reparto WHERE id = NEW.reparto_id;

    SELECT instancia_produccion_id INTO v_instancia_detalle
    FROM detalle_instancia_de_produccion
    WHERE id = NEW.detalle_instancia_produccion_id;

    IF v_instancia_reparto IS DISTINCT FROM v_instancia_detalle THEN
        RAISE EXCEPTION 'Reparto % y detalle de produccion % pertenecen a distintas instancias',
            NEW.reparto_id, NEW.detalle_instancia_produccion_id;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_validar_detalle_reparto
BEFORE INSERT OR UPDATE OF reparto_id, detalle_instancia_produccion_id
ON detalle_reparto FOR EACH ROW EXECUTE FUNCTION validar_detalle_reparto();

COMMIT;

-- TABLAS: 44 (FactorComplejidad se modela como CHECK del atributo, tal
-- como aparece en el DER y no como tabla separada).
-- Las funciones/triggers validan consistencia cruzada sin agregar entidades.
